import {describe, expect, it} from 'vitest';
import {hashPassword, verifyPassword} from './passwords.js';

// Generated by the Python app's own hash_profile_password('correct horse ünïcode').
const PYTHON_HASH = 'pbkdf2_sha256$0ce2722220d400e18c2134109203b6f2$80b3a18caace9e01865172c609811d8392d0696a0aaf19a716e685635b709eec';

describe('passwords', () => {
    it('verifies hashes created by the Python app', () => {
        expect(verifyPassword('correct horse ünïcode', PYTHON_HASH)).toBe(true);
        expect(verifyPassword('correct horse unicode', PYTHON_HASH)).toBe(false);
    });

    it('round-trips new hashes', () => {
        const hash = hashPassword('s3cret!');
        expect(hash).toMatch(/^pbkdf2_sha256\$600000\$[0-9a-f]{32}\$[0-9a-f]{64}$/);
        expect(verifyPassword('s3cret!', hash)).toBe(true);
        expect(verifyPassword('s3cret', hash)).toBe(false);
    });

    it('rejects missing or malformed hashes', () => {
        for (const stored of [null, undefined, '', 'bcrypt$x', 'pbkdf2_sha256$only-two', 'pbkdf2_sha256$x$y$z', 'pbkdf2_sha256$salt$abcd']) {
            expect(verifyPassword('anything', stored)).toBe(false);
        }
    });
});
